pub fn catalog_transition_violation_prefix() -> Vec<u8> {
    vec![0x72, 0x37, CATALOG_TRANSITION_VIOLATION_TAG]
}

/// Scan prefix covering every `catalog_transition_violation` key through `transition`.
pub fn catalog_transition_violation_prefix_transition(transition: u64) -> Vec<u8> {
    let mut key = catalog_transition_violation_prefix();
    append_uvarint(&mut key, transition);
    key
}

pub fn catalog_transition_violation_key(transition: u64, row_identity: &[u8]) -> Vec<u8> {
    let mut key = catalog_transition_violation_prefix();
    append_uvarint(&mut key, transition);
    key.extend_from_slice(row_identity);
    key
}

#[derive(Debug, Eq, PartialEq)]
pub struct CatalogTransitionViolationKeyParts {
    pub transition: u64,
    pub row_identity: Vec<u8>,
}

pub fn decode_catalog_transition_violation_key(
    key: &[u8],
) -> Option<CatalogTransitionViolationKeyParts> {
    let rest = key.strip_prefix(&[0x72, 0x37, CATALOG_TRANSITION_VIOLATION_TAG][..])?;
    let mut position = 0;
    let transition = read_uvarint(rest, &mut position)?;
    let row_identity = rest[position..].to_vec();
    position = rest.len();
    if position != rest.len() {
        return None;
    }
    Some(CatalogTransitionViolationKeyParts {
        transition,
        row_identity,
    })
}

